package com.bank.pnl.service;

import com.bank.pnl.dto.PnlReport;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Stream;

@Service
@Slf4j
public class PnlService {

    record Trade(String id, String symbol, BigDecimal buyPrice, BigDecimal sellPrice, int qty) {
        BigDecimal pnl() { return sellPrice.subtract(buyPrice).multiply(BigDecimal.valueOf(qty)); }
    }

    private final List<Trade> trades = List.of(
        new Trade("T1", "RELIANCE", bd("2200"), bd("2450"), 100),   // +25000
        new Trade("T2", "TCS",      bd("3520"), bd("3300"), 50),    // -11000
        new Trade("T3", "HDFC",     bd("1650"), bd("1700"), 200),   // +10000
        new Trade("T4", "INFY",     bd("1500"), bd("1480"), 150),   // -3000
        new Trade("T5", "WIPRO",    bd("420"),  bd("460"),  80)     // +3200
    );

    public PnlReport generatePnlReport() {

        // ═══ MAP: transform each Trade → BigDecimal P&L (N→N) ═══
        List<BigDecimal> pnlValues = trades.stream()
            .map(Trade::pnl)               // INTERMEDIATE: 5 trades → 5 P&L values
            .toList();
        log.info("[map] {} trades → {} P&L values: {}", trades.size(), pnlValues.size(), pnlValues);

        // ═══ REDUCE: aggregate all P&L → one total (N→1) ═══
        BigDecimal totalPnl = trades.stream()
            .map(Trade::pnl)               // map: Trade → BigDecimal (transform)
            .reduce(BigDecimal.ZERO, BigDecimal::add);  // reduce: all → sum (aggregate)
        log.info("[map+reduce] Total P&L: Rs.{}", totalPnl);

        // ═══ REDUCE: find largest profit ═══
        BigDecimal largestProfit = trades.stream()
            .map(Trade::pnl)
            .filter(p -> p.signum() > 0)   // only profits
            .reduce(BigDecimal.ZERO, BigDecimal::max);
        log.info("[reduce max] Largest profit: Rs.{}", largestProfit);

        // ═══ REDUCE: find largest loss ═══
        BigDecimal largestLoss = trades.stream()
            .map(Trade::pnl)
            .filter(p -> p.signum() < 0)
            .reduce(BigDecimal.ZERO, BigDecimal::min);
        log.info("[reduce min] Largest loss: Rs.{}", largestLoss);

        // ═══ MAP + REDUCE: build CSV string ═══
        String csv = trades.stream()
            .map(Trade::symbol)            // map: Trade → String
            .distinct()
            .reduce("", (a, b) -> a.isEmpty() ? b : a + ", " + b);  // reduce: concat
        log.info("[reduce concat] Symbols: {}", csv);

        return new PnlReport(trades.size(), totalPnl, largestProfit, largestLoss, csv,
            "map: 5 Trades → 5 P&L BigDecimals (N→N, intermediate, lazy)",
            "reduce: 5 P&L BigDecimals → 1 total (N→1, terminal, eager)");
    }

    private static BigDecimal bd(String v) { return new BigDecimal(v); }
}
```

