package com.bank.pnl.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class MapVsReduceTest {

    @Test
    void mapTransformsEachElement() {
        List<Integer> lengths = Stream.of("RELIANCE", "TCS", "HDFC")
            .map(String::length)      // 3 strings → 3 integers (N→N)
            .toList();
        assertThat(lengths).containsExactly(8, 3, 4);
        assertThat(lengths).hasSize(3);  // same count as input
    }

    @Test
    void reduceAggregatesIntoOne() {
        int totalLength = Stream.of("RELIANCE", "TCS", "HDFC")
            .map(String::length)     // map: 3 strings → 3 ints
            .reduce(0, Integer::sum); // reduce: 3 ints → 1 sum
        assertThat(totalLength).isEqualTo(15);  // 8+3+4
    }

    @Test
    void reduceWithoutIdentityReturnsOptional() {
        Optional<BigDecimal> max = Stream.of("100", "300", "200")
            .map(BigDecimal::new)
            .reduce(BigDecimal::max);
        assertThat(max).contains(new BigDecimal("300"));

        Optional<BigDecimal> emptyMax = Stream.<BigDecimal>empty()
            .reduce(BigDecimal::max);
        assertThat(emptyMax).isEmpty();
    }

    @Test
    void mapAndReduceWorkTogether() {
        BigDecimal total = Stream.of(100, 200, 300)
            .map(BigDecimal::valueOf)                    // map: Integer → BigDecimal
            .reduce(BigDecimal.ZERO, BigDecimal::add);   // reduce: sum
        assertThat(total).isEqualByComparingTo("600");
    }

    @Test
    void reduceCanBuildStrings() {
        String csv = Stream.of("RELIANCE", "TCS", "HDFC")
            .reduce("", (a, b) -> a.isEmpty() ? b : a + ", " + b);
        assertThat(csv).isEqualTo("RELIANCE, TCS, HDFC");
    }
}
